	private ListBuffer<JCExpression> getTypeParamExpressions(List<? extends JCTree> typeParams, JavacTreeMaker maker, JavacNode source) {
		ListBuffer<JCExpression> typeParamsForBuilderParameter = new ListBuffer<JCExpression>();
		for (JCTree typeParam : typeParams) {
			if (typeParam instanceof JCTypeParameter) {
				JCTypeParameter declaredTypeParameter = (JCTypeParameter) typeParam;
				Name typeParameterName = declaredTypeParameter.getName();
				Name resolvedTypeParameterName = source.toName(typeParameterName.toString());
				JCExpression typeParameterRef = maker.Ident(resolvedTypeParameterName);
				typeParamsForBuilderParameter.append(typeParameterRef);
			} else if (typeParam instanceof JCIdent) {
				JCIdent identType = (JCIdent) typeParam;
				Name identName = identType.getName();
				Name resolvedIdentName = source.toName(identName.toString());
				JCExpression identRef = maker.Ident(resolvedIdentName);
				typeParamsForBuilderParameter.append(identRef);
			} else if (typeParam instanceof JCFieldAccess) {
				java.util.List<Name> chainNames = new ArrayList<Name>();
				JCExpression expression = (JCFieldAccess) typeParam;
				while (expression != null) {
					if (expression instanceof JCFieldAccess) {
						JCFieldAccess fieldAccess = (JCFieldAccess) expression;
						chainNames.add(fieldAccess.getIdentifier());
						expression = fieldAccess.getExpression();
					} else if (expression instanceof JCIdent) {
						JCIdent ident = (JCIdent) expression;
						chainNames.add(ident.getName());
						expression = null;
					}
				}
				Collections.reverse(chainNames);
				JCExpression typeParameter = null;
				for (Name name : chainNames) {
					Name resolvedName = source.toName(name.toString());
					if (typeParameter == null) {
						typeParameter = maker.Ident(resolvedName);
					} else {
						typeParameter = maker.Select(typeParameter, resolvedName);
					}
				}
				typeParamsForBuilderParameter.append(typeParameter);
			} else if (typeParam instanceof JCTypeApply) {
				JCTypeApply typeApply = (JCTypeApply) typeParam;
				JCExpression classPart = typeApply.clazz;
				JCExpression clonedClass;
				if (classPart instanceof JCIdent) {
					JCIdent classIdent = (JCIdent) classPart;
					clonedClass = maker.Ident(source.toName(classIdent.getName().toString()));
				} else {
					clonedClass = cloneType(maker, classPart, source);
				}
				ListBuffer<JCExpression> clonedArguments = new ListBuffer<JCExpression>();
				for (JCExpression typeArg : typeApply.arguments) {
					if (typeArg instanceof JCIdent) {
						JCIdent argIdent = (JCIdent) typeArg;
						clonedArguments.append(maker.Ident(source.toName(argIdent.getName().toString())));
					} else if (typeArg instanceof JCArrayTypeTree) {
						JCArrayTypeTree arrayType = (JCArrayTypeTree) typeArg;
						JCExpression clonedElementType = cloneType(maker, arrayType.elemtype, source);
						clonedArguments.append(maker.TypeArray(clonedElementType));
					} else {
						clonedArguments.append(cloneType(maker, typeArg, source));
					}
				}
